import { redirect } from 'next/navigation'
import { db } from '@/lib/db'
import { getSession } from '@/lib/session'
import { RenameForm } from './RenameForm'

export default async function TodosPage() {
  const session = await getSession()
  if (!session) redirect('/login')

  const todos = await db.todo.findMany({ where: { userId: session.userId } })
  return (
    <ul>
      {todos.map((todo) => (
        <li key={todo.id}>
          <RenameForm id={todo.id} title={todo.title} />
        </li>
      ))}
    </ul>
  )
}

'use client'

import { useState, type FormEvent } from 'react'
import { useRouter } from 'next/navigation'

export function RenameForm({ id, title }: { id: string; title: string }) {
  const router = useRouter()
  const [error, setError] = useState<string | null>(null)

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const res = await fetch(`/api/todos/${id}`, {
      method: 'PATCH',
      body: JSON.stringify({ title: form.get('title') }),
    })
    if (!res.ok) {
      setError('Could not rename')
      return
    }
    router.refresh()
  }

  return (
    <form onSubmit={handleSubmit}>
      <input name="title" defaultValue={title} />
      <button type="submit">Rename</button>
      {error && <p role="alert">{error}</p>}
    </form>
  )
}

import { NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { getSession } from '@/lib/session'

type Context = { params: Promise<{ id: string }> }

export async function PATCH(request: Request, { params }: Context) {
  const session = await getSession()
  if (!session) {
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  }
  const { id } = await params
  const { title } = await request.json()
  await db.todo.updateMany({ where: { id, userId: session.userId }, data: { title } })
  return NextResponse.json({ ok: true })
}

