'use server'

import { revalidatePath } from 'next/cache'
import { db } from '@/lib/db'

export type RenameState = { error: string | null }

export async function renameTodo(
  _prev: RenameState,
  formData: FormData,
): Promise<RenameState> {
  const id = formData.get('id') as string
  const title = formData.get('title') as string

  await db.todo.update({ where: { id }, data: { title } })
  revalidatePath('/todos')
  return { error: null }
}

'use client'

import { useActionState } from 'react'
import { renameTodo } from './actions'

export function RenameForm({ id, title }: { id: string; title: string }) {
  const [state, formAction, isPending] = useActionState(renameTodo, { error: null })

  return (
    <form action={formAction}>
      <input type="hidden" name="id" value={id} />
      <input name="title" defaultValue={title} />
      <button type="submit" disabled={isPending}>Rename</button>
      {state.error && <p role="alert">{state.error}</p>}
    </form>
  )
}

'use server'

import { revalidatePath } from 'next/cache'
import { db } from '@/lib/db'
import { getSession } from '@/lib/session'

export type RenameState = { error: string | null }

export async function renameTodo(
  _prev: RenameState,
  formData: FormData,
): Promise<RenameState> {
  const session = await getSession()
  if (!session) return { error: 'Please sign in again' }

  const id = formData.get('id')
  const title = formData.get('title')
  if (typeof id !== 'string' || typeof title !== 'string') {
    return { error: 'Invalid form' }
  }
  const trimmed = title.trim()
  if (trimmed === '' || trimmed.length > 100) {
    return { error: 'Title must be 1 to 100 characters' }
  }

  const { count } = await db.todo.updateMany({
    where: { id, userId: session.userId },
    data: { title: trimmed },
  })
  if (count === 0) return { error: 'Todo not found' }

  revalidatePath('/todos')
  return { error: null }
}
